case.when:
${(() => {
  const raw = $context.outputs?.v2_generateChatCompletion_1?.content?.text || "{}";
  const cleaned = typeof raw === "string" ? raw.replace(/```json|```/g, "").trim() : JSON.stringify(raw);
  const parsed = JSON.parse(cleaned);
  return parsed.sentiment === "Urgent_Negative";
})()
}

